pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 rand_prev, uint256 rand_cur, uint256 extra_payments) public {
        // Admissible domain: random values are uint256 but we need them to produce win/lose outcomes.
        // We simulate the conditions by controlling block.timestamp and block.difficulty.
        // First, ensure we have two distinct actors with enough ETH.
        address alice = address(0x1000);
        address bob = address(0x2000);
        vm.deal(alice, 100 ether);
        vm.deal(bob, 100 ether);

        // Step 1: Force first play to either win or lose based on rand_prev.
        // We manipulate block.difficulty and block.timestamp to produce the desired outcome.
        // Use rand_prev to decide the outcome: if rand_prev % 2 == 0 -> win, else lose.
        uint difficulty_prev = rand_prev % 2 == 0 ? 0 : 1;
        vm.warp(1);
        vm.difficulty(difficulty_prev);
        vm.prank(alice);
        c.play{value: 10}();

        // Record pot after first play.
        uint pot_after_first = c.pot();

        // Step 2: Make extra payments to pot directly by playing and losing.
        // To guarantee a loss, ensure (keccak256(abi.encodePacked(timestamp, difficulty)) % 2 == 1).
        // We can do this by setting difficulty = 1 and timestamp such that result is odd.
        // Simpler: just make many plays that lose, accumulating value.
        // We'll use a fuzzed number of extra payments (bound to prevent overflow).
        uint num_payments = extra_payments % 10; // 0..9 extra payments
        for (uint i = 0; i < num_payments; i++) {
            // Ensure loss: difficulty = 1, timestamp = 2*i + 1000 (any value yielding odd hash)
            // keccak256(abi.encodePacked(timestamp, 1)) is odd for some timestamps. We brute-force with vm.warp.
            vm.warp(1000 + i * 10);
            vm.difficulty(1);
            // Use bob for these payments to avoid confusion
            vm.prank(bob);
            c.play{value: 10}();
        }

        // Record pot before the decisive second play for alice.
        uint pot_before_second = c.pot();
        // Balance of alice before second play
        uint alice_balance_before = alice.balance;

        // Step 3: Force a win for alice in the second play.
        vm.warp(2000);
        vm.difficulty(0); // ensures keccak256(abi.encodePacked(2000, 0)) % 2 == 0 for most cases
        vm.prank(alice);
        c.play{value: 10}();

        uint pot_after_second = c.pot();
        uint alice_balance_after = alice.balance;

        // The general rule:
        // If alice won the second play (pot_before_second > 0), the pot must be reset to 0.
        // The reference implementation does this; the mutant fails to reset, so pot > 0.
        // More generally: after any win where pot > 0, pot must become 0.
        // Since we forced a win in the second play, the pot must be 0 after it, regardless of previous history.
        assertTrue(pot_after_second == 0);
    }
}

