contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 seed, uint8 numCalls) public {
        // At least one call to play
        vm.assume(numCalls >= 1 && numCalls <= 10);

        address player = address(uint160(uint256(keccak256(abi.encode(seed, "player")))));
        vm.deal(player, 10 * numCalls);

        bool lastWasWin = false;

        for (uint8 i = 0; i < numCalls; i++) {
            vm.roll(seed + i + 1);
            vm.warp(seed + i + 1);
            vm.prank(player);
            // To detect revert without halting the loop
            try c.play{value: 10}() { 
                // Pot after a win should be 0
                if (lastWasWin) {
                    assertTrue(c.pot() == 0);
                }
                // Determine if current call was a win by checking if pot is 0 or not
                // Since pot is only reset to 0 on win in reference, and never reset in mutant,
                // we can infer win by pot == 0 (reference) or pot > 0 (mutant).
                // However, we need a condition that holds for reference regardless of win/loss.
                // Reference: after any call, if pot == 0, then the call just paid out (win).
                // Mutant: pot never resets, so pot != 0 after win.
                // So: After a call where pot becomes 0, it must be a win.
                // But we need a property that always holds for reference, and fails for mutant.
                // Simpler: After two consecutive wins, reference pot == 0, mutant pot > 0.
                // We detect win by pot == 0 after call (only in reference).
                // Actually, we can just track if we observed pot == 0 after a call (reference).
                // In mutant, pot never becomes 0 after a win.
                if (c.pot() == 0) {
                    lastWasWin = true;
                } else {
                    lastWasWin = false;
                }
            } catch {
                // revert is fine for both, just continue
            }
        }
    }
}

