pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address player) public {
        vm.assume(player != address(0) && player != address(c) && player != address(this));

        uint constant TICKET = 10;
        uint constant FEE = 1;

        // Fund the player
        vm.deal(player, TICKET);
        vm.prank(player);
        c.play{value: TICKET}();

        // Check pot invariant: if a prize transfer occurred (random 0), pot must be 0 after the call.
        // We cannot force random=0, so by fuzzing the player we eventually hit the branch.
        // We assert that pot can never be non-zero when the contract balance is less than pot,
        // which is exactly the M scenario after fee deduction.
        // General rule: If pot > 0, then address(c).balance >= pot.
        uint currentPot = c.pot();
        uint contractBalance = address(c).balance;
        assertTrue(currentPot == 0 || contractBalance >= currentPot);
    }
}

